const c=-4,u=[{intervals:4,points:50},{intervals:3,points:30},{intervals:2,points:15},{intervals:1,points:5}];export const SACK=-5,INTERCEPTION=-10;export function pointsForPosition(t,o){for(const n of u)if(t>=-4+o*n.intervals)return n.points;return 0}export function classifyPlay({ranWithBall:t,threwTo:o,ball:n,carrierX:e,lineInterval:r,reached50:a}){if(!t&&!o)return{result:"sack",points:SACK,headline:"Sacked",detail:"Nobody got the ball away in time."};if(!t){if(!n||!n.caught)return{result:"incomplete",points:0,headline:"Incomplete",detail:"The pass fell to the turf."};if(n.team!==0)return{result:"interception",points:INTERCEPTION,headline:"Intercepted",detail:"The Crows read it and took the ball away."};const s=pointsForPosition(e,r);return{result:"catch",points:s,headline:s===50?"All the way":"Caught",detail:s===50?"Caught and carried the whole way across.":`Caught and brought down for ${s}.`}}const i=pointsForPosition(e,r);return{result:a?"run-50":"run",points:i,headline:i===50?"All the way":"Kept it",detail:i===50?"Tucked it and ran the whole way across.":`Tucked it and ran for ${i}.`}}export function summarise(t){const o=t.reduce((e,r)=>e+r.points,0),n=t.reduce((e,r)=>r.points>e.points?r:e,t[0]||{points:0});return{total:o,plays:t.length,best:n?n.points:0,scored:t.filter(e=>e.points>0).length,gaveAway:t.filter(e=>e.points<0).length}}export function verdictFor(t){return t>=300?"A clinic.":t>=200?"A very good afternoon.":t>=120?"Solid work.":t>=60?"Moved the ball.":t>0?"Hard yards.":"One of those games."}
